import React, { useState, useEffect } from "react";
import { NavLink, useNavigate } from "react-router-dom";

const MenuItems = () => {
  const navigate = useNavigate();
  const [isAccountOpen, setIsAccountOpen] = useState(false); // menu tài khoản
  const [user, setUser] = useState(null); // lưu thông tin user nếu đăng nhập

  // Kiểm tra đăng nhập khi component load
  useEffect(() => {
    const userInfo = localStorage.getItem("userInfo");
    if (userInfo) setUser(JSON.parse(userInfo));
  }, []);

  // Xử lý logout
  const handleLogout = () => {
    localStorage.removeItem("authToken");
    localStorage.removeItem("userInfo");
    setUser(null);
    setIsAccountOpen(false);
    navigate("/login");
  };

  return (
    <div className="menu-items flex items-center gap-4 relative">
      <NavLink
        to="/gioithieu"
        className={({ isActive }) => (isActive ? "menu-link active" : "menu-link")}
      >
        Giới thiệu
      </NavLink>

      <NavLink
        to="/marketplace"
        className={({ isActive }) => (isActive ? "menu-link active" : "menu-link")}
      >
        Marketplace
      </NavLink>

      <NavLink
        to="/news"
        className={({ isActive }) => (isActive ? "menu-link active" : "menu-link")}
      >
        Tin tức
      </NavLink>

      <NavLink
        to="/support"
        className={({ isActive }) => (isActive ? "menu-link active" : "menu-link")}
      >
        Hỗ trợ
      </NavLink>

      <NavLink
        to="/contact"
        className={({ isActive }) => (isActive ? "menu-link active" : "menu-link")}
      >
        Liên hệ
      </NavLink>

      {/* Menu Tài khoản */}
      <div className="relative">
        <button
          onClick={() => setIsAccountOpen(!isAccountOpen)}
          className="menu-link flex items-center gap-1"
        >
          👤 Tài khoản
        </button>

        {isAccountOpen && (
          <div className="absolute right-0 mt-2 w-48 bg-white border rounded shadow-lg z-50">
            {user ? (
              <div>
                <div className="px-4 py-2 text-gray-800">{user.name}</div>
                <button
                  className="w-full text-left px-4 py-2 hover:bg-gray-100"
                  onClick={handleLogout}
                >
                  Đăng xuất
                </button>
              </div>
            ) : (
              <button
                className="w-full text-left px-4 py-2 hover:bg-gray-100"
                onClick={() => {
                  navigate("/auth");
                  setIsAccountOpen(false);
                }}
              >
                Đăng nhập
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default MenuItems;
